### **5. Dequeue and Transition: "queued" → "processing"**

**File: `./Users/timokurz/Developer/craft-agents-oss/packages/server-core/src/sessions/SessionManager.ts` (lines 5519-5566)**

```typescript
private processNextQueuedMessage(sessionId: string): void {
  const managed = this.sessions.get(sessionId)
  if (!managed || managed.messageQueue.length === 0) return

  // DEQUEUE
  const next = managed.messageQueue.shift()!
  sessionLog.info(`Processing queued message for session ${sessionId}`)

  // UPDATE UI: queued → processing
  if (next.messageId) {
    const existingMessage = managed.messages.find(m => m.id === next.messageId)
    if (existingMessage) {
      // Clear isQueued flag and persist - prevents re-queueing if crash
      existingMessage.isQueued = false
      this.persistSession(managed)

      this.sendEvent({
        type: 'user_message',
        sessionId,
        message: existingMessage,
        status: 'processing',  // ← Transition from queued to processing
        optimisticMessageId: next.optimisticMessageId
      }, managed.workspace.id)
    }
  }

  // PROCESS MESSAGE (use setImmediate to allow stack to clear)
  setImmediate(() => {
    this.sendMessage(
      sessionId,
      next.message,
      next.attachments,
      next.storedAttachments,
      next.options,
      next.messageId  // ← Pass existing message ID to reuse it
    ).catch(err => {
      // Error handling calls onProcessingStopped again for queue recursion
      this.onProcessingStopped(sessionId, 'error')
    })
  })
}
```

