194→  const errorFile = getErrorFilePath();
195→  try {
196→    if (error) {
197→      writeFileSync(errorFile, JSON.stringify(error));
198→      debugLog(`[setStoredError] Wrote error to file: ${error.status} ${error.message}`);
199→    } else {
200→      try {
201→        unlinkSync(errorFile);
202→      } catch {
203→        // File might not exist
204→      }
205→    }
206→  } catch (e) {
207→    debugLog(`[setStoredError] Failed to write: ${e}`);
208→  }
209→}
210→
211→export function getLastApiError(sessionDir?: string): LastApiError | null {
212→  const error = getStoredError(sessionDir);
213→  if (error) {
214→    const age = Date.now() - error.timestamp;
215→    if (age < MAX_ERROR_AGE_MS) {
216→      debugLog(`[getLastApiError] Found error (age ${age}ms): ${error.status}`);
217→      return error;
218→    }
219→    debugLog(`[getLastApiError] Error too old (${age}ms > ${MAX_ERROR_AGE_MS}ms)`);
220→  }
221→  return null;
222→}
223→
224→export function clearLastApiError(): void {
225→  setStoredError(null);
226→}
