228→// ============================================================================
229→// TOOL METADATA STORE
230→// ============================================================================
231→
232→/**
233→ * Metadata extracted from tool_use inputs by the SSE stripping/capture stream.
234→ * Keyed by tool_use_id, consumed by tool-matching.ts / event-adapter.ts.
235→ */
236→export interface ToolMetadata {
237→  intent?: string;
238→  displayName?: string;
239→  timestamp: number;
240→}
241→
242→/**
243→ * Session-scoped, file-based metadata store for cross-process sharing.
244→ *
245→ * The interceptor runs in the SDK subprocess (via --preload / --require),
246→ * while tool-matching.ts / event-adapter.ts run in the Electron main process.
247→ * These are separate OS processes — globalThis, module-level Maps, etc. are NOT shared.
248→ *
249→ * Solution: a single `tool-metadata.json` file in the session directory.
250→ * - set() writes to both in-memory Map AND merges into {sessionDir}/tool-metadata.json
251→ * - get() checks in-memory Map first (same-process), then reads from file
252→ * - No cleanup needed: file lives with the session, deleted when session is deleted
253→ * - Survives subprocess restarts (session resume) via file persistence
254→ *
255→ * The session directory is determined by:
256→ * - SDK subprocess: CRAFT_SESSION_DIR env var (set by main process before spawn)
257→ * - Main process: toolMetadataStore.setSessionDir(path) called during agent creation
258→ *
259→ * IMPORTANT: Multiple sessions can run concurrently in the main process (parallel chats,
260→ * title generation, etc.). The singleton _sessionDir gets clobbered by whichever session
261→ * calls setSessionDir() last. To handle this, get() accepts an explicit sessionDir
262→ * parameter, and setSessionDir() merges (not replaces) the in-memory map so entries
263→ * from all sessions coexist safely (tool_use_ids are globally unique UUIDs).
264→ */
265→
266→function getMetadataFilePath(): string | null {
267→  return _sessionDir ? join(_sessionDir, 'tool-metadata.json') : null;
268→}
269→
270→/** Read metadata from a specific session directory's file */
271→function readMetadataFileFromDir(dir: string): Record<string, ToolMetadata> {
272→  try {
273→    const filePath = join(dir, 'tool-metadata.json');
274→    const data = readFileSync(filePath, 'utf-8');
275→    return JSON.parse(data) as Record<string, ToolMetadata>;
276→  } catch (error) {
277→    debugLog(`[toolMetadataStore.read] Failed for dir=${dir}: ${error instanceof Error ? error.message : String(error)}`);
278→    return {};
279→  }
280→}
281→
282→// In-memory Map for same-process lookups (accumulates entries across all sessions)
283→const _metadataMap = new Map<string, ToolMetadata>();
284→
285→/** Read the entire metadata file from disk (uses current _sessionDir) */
286→function readMetadataFile(): Record<string, ToolMetadata> {
287→  if (!_sessionDir) return {};
288→  return readMetadataFileFromDir(_sessionDir);
289→}
290→
291→/** Write the entire metadata object to the session file (atomic via temp+rename) */
292→function writeMetadataFile(allMetadata: Record<string, ToolMetadata>): void {
293→  const filePath = getMetadataFilePath();
294→  if (!filePath) return;
295→  try {
296→    const tmpPath = filePath + '.tmp';
297→    writeFileSync(tmpPath, JSON.stringify(allMetadata));
298→    renameSync(tmpPath, filePath);
299→  } catch (error) {
300→    // Keep non-throwing behavior, but log for diagnostics.
301→    debugLog(`[toolMetadataStore.write] Failed for file=${filePath}: ${error instanceof Error ? error.message : String(error)}`);
302→  }
303→}
304→
305→/**
306→ * Merge an updater into the latest on-disk metadata and write atomically.
307→ * Retries once to reduce lost updates under concurrent writers.
308→ */
309→function mergeAndWriteMetadata(
310→  updater: (all: Record<string, ToolMetadata>) => void,
311→  retries: number = 1,
312→): void {
313→  for (let attempt = 0; attempt <= retries; attempt++) {
314→    try {
315→      const all = readMetadataFile();
316→      updater(all);
317→      writeMetadataFile(all);
318→      return;
319→    } catch (error) {
320→      debugLog(`[toolMetadataStore.merge] Attempt ${attempt + 1}/${retries + 1} failed: ${error instanceof Error ? error.message : String(error)}`);
321→      if (attempt === retries) return;
322→    }
323→  }
324→}
325→
326→export const toolMetadataStore = {
327→  /**
328→   * Set session directory and pre-populate in-memory map from file.
329→   * Called by main process so subsequent get() calls are O(1) memory lookups.
330→   * Does NOT clear the map — entries from other sessions are preserved since
331→   * tool_use_ids are globally unique UUIDs and won't conflict.
332→   */
333→  setSessionDir(dir: string): void {
334→    _sessionDir = dir;
335→    // Merge, don't clear — concurrent sessions share this singleton and
336→    // clearing would discard metadata from other active sessions.
337→    const all = readMetadataFile();
338→    for (const [id, meta] of Object.entries(all)) {
339→      _metadataMap.set(id, meta);
340→    }
341→  },
342→
343→  /** Store metadata — writes to in-memory Map + cached file */
344→  set(toolUseId: string, metadata: ToolMetadata): void {
345→    _metadataMap.set(toolUseId, metadata);
346→    mergeAndWriteMetadata((all) => {
347→      all[toolUseId] = metadata;
348→    });
349→  },
350→
351→  /**
352→   * Read metadata — checks in-memory first, then session file.
353→   * Accepts an explicit sessionDir to read from the correct file even when
354→   * _sessionDir has been clobbered by a concurrent session's setSessionDir().
355→   */
356→  get(toolUseId: string, sessionDir?: string): ToolMetadata | undefined {
357→    const inMemory = _metadataMap.get(toolUseId);
358→    if (inMemory) return inMemory;
359→
360→    // Read from explicit sessionDir if provided, otherwise fall back to _sessionDir
361→    const dir = sessionDir || _sessionDir;
362→    if (!dir) return undefined;
363→
364→    const all = readMetadataFileFromDir(dir);
365→    const entry = all[toolUseId];
366→    if (entry) {
367→      // Cache in memory for O(1) subsequent lookups
368→      _metadataMap.set(toolUseId, entry);
369→    }
370→    return entry;
371→  },
372→
373→  delete(toolUseId: string): void {
374→    _metadataMap.delete(toolUseId);
375→    mergeAndWriteMetadata((all) => {
376→      delete all[toolUseId];
377→    });
378→  },
379→
380→  get size(): number {
381→    return _metadataMap.size;
382→  },
383→
384→  /** Clear all in-memory entries. Used by tests to prevent cross-file state leaks. */
385→  _clearForTesting(): void {
386→    _metadataMap.clear();
387→  },
388→};
