  1→import { existsSync } from 'node:fs';
  2→import { execFileSync } from 'node:child_process';
  3→import { dirname, join, resolve } from 'node:path';
  4→import type { BackendHostRuntimeContext } from '../types.ts';
  5→import {
  6→  setExecutable,
  7→  setInterceptorPath,
  8→  setPathToClaudeCodeExecutable,
  9→} from '../.../options.ts';
 10→
 11→/**
 12→ * When set, the resolver walks further up from the .app bundle to find SDK,
 13→ * interceptor, and bun in the monorepo / on the system PATH.
 14→ * Intended for local `electron:dist:mac` builds that skip `build-dmg.sh`.
 15→ */
 16→const IS_DEV_RUNTIME = !!process.env.CRAFT_DEV_RUNTIME;
 17→
 18→export interface ResolvedBackendRuntimePaths {
 19→  claudeCliPath?: string;
 20→  claudeInterceptorPath?: string;
 21→  interceptorBundlePath?: string;
 22→  copilotCliPath?: string;
 23→  sessionServerPath?: string;
 24→  bridgeServerPath?: string;
 25→  piServerPath?: string;
 26→  nodeRuntimePath?: string;
 27→  bundledRuntimePath?: string;
 28→}
 29→
 30→export interface ResolvedBackendHostTooling {
 31→  ripgrepPath?: string;
 32→}
 33→
 34→function firstExistingPath(candidates: string[]): string | undefined {
 35→  for (const candidate of candidates) {
 36→    if (existsSync(candidate)) return candidate;
 37→  }
 38→  return undefined;
 39→}
 40→
 41→/**
 42→ * Walk up from `base` checking `join(ancestor, relativePath)` at each level.
 43→ * Stops after `maxLevels` ancestors or when hitting the filesystem root.
 44→ */
 45→function resolveUpwards(base: string, relativePath: string, maxLevels = 4): string | undefined {
 46→  let dir = resolve(base);
 47→  for (let i = 0; i <= maxLevels; i++) {
 48→    const candidate = join(dir, relativePath);
 49→    if (existsSync(candidate)) return candidate;
 50→    const parent = dirname(dir);
 51→    if (parent === dir) break; // filesystem root
 52→    dir = parent;
 53→  }
 54→  return undefined;
 55→}
 56→
 57→function resolveBundledRuntimePath(hostRuntime: BackendHostRuntimeContext): string | undefined {
 58→  const bunBinary = process.platform === 'win32' ? 'bun.exe' : 'bun';
 59→  const bunBasePath = process.platform === 'win32'
 60→    ? (hostRuntime.resourcesPath || hostRuntime.appRootPath)
 61→    : hostRuntime.appRootPath;
 62→  const bunPath = join(bunBasePath, 'vendor', 'bun', bunBinary);
 63→  if (existsSync(bunPath)) return bunPath;
 64→
 65→  // Non-packaged (headless server, dev mode): fall back to system bun via PATH.
 66→  // Packaged apps must ship their own bundled bun — never resolve from PATH
 67→  // to avoid picking up an incompatible system install.
 68→  if (!hostRuntime.isPackaged) {
 69→    try {
 70→      const whichCmd = process.platform === 'win32' ? 'where' : 'which';
 71→      const systemBun = execFileSync(whichCmd, ['bun'], { encoding: 'utf-8' }).trim();
 72→      if (systemBun && existsSync(systemBun)) return systemBun;
 73→    } catch { /* system bun not found */ }
 74→  }
 75→  return undefined;
 76→}
 77→
 78→function resolveClaudeCliPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
 79→  const sdkRelative = join('node_modules', '@anthropic-ai', 'claude-agent-sdk', 'cli.js');
 80→  const result = firstExistingPath([
 81→    join(hostRuntime.appRootPath, sdkRelative),
 82→    join(hostRuntime.appRootPath, '..', '..', sdkRelative),
 83→  ]);
 84→  if (result) return result;
 85→
 86→  // Dev runtime: walk further up from .app bundle to reach monorepo root
 87→  if (IS_DEV_RUNTIME) {
 88→    return resolveUpwards(hostRuntime.appRootPath, sdkRelative, 10);
 89→  }
 90→  return undefined;
 91→}
 92→
 93→function resolveClaudeInterceptorPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
 94→  const interceptorRelative = join('packages', 'shared', 'src', 'unified-network-interceptor.ts');
 95→  const result = firstExistingPath([
 96→    join(hostRuntime.appRootPath, interceptorRelative),
 97→    join(hostRuntime.appRootPath, '..', '..', interceptorRelative),
 98→  ]);
 99→  if (result) return result;
100→
101→  // Dev runtime: walk further up from .app bundle to reach monorepo root
102→  if (IS_DEV_RUNTIME) {
103→    return resolveUpwards(hostRuntime.appRootPath, interceptorRelative, 10);
104→  }
105→  return undefined;
106→}
107→
108→function resolveInterceptorBundlePath(hostRuntime: BackendHostRuntimeContext): string | undefined {
109→  if (hostRuntime.interceptorBundlePath && existsSync(hostRuntime.interceptorBundlePath)) {
110→    return hostRuntime.interceptorBundlePath;
111→  }
112→
113→  return resolveUpwards(hostRuntime.appRootPath, join('dist', 'interceptor.cjs'))
114→    ?? resolveUpwards(hostRuntime.appRootPath, join('apps', 'electron', 'dist', 'interceptor.cjs'));
115→}
116→
117→function resolveCopilotCliPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
118→  const platform = process.platform === 'win32'
119→    ? 'win32'
120→    : process.platform === 'linux'
121→      ? 'linux'
122→      : 'darwin';
123→  const arch = process.arch === 'arm64' ? 'arm64' : 'x64';
124→  const binaryName = platform === 'win32' ? 'copilot.exe' : 'copilot';
125→
126→  if (hostRuntime.isPackaged) {
127→    const packaged = join(hostRuntime.appRootPath, 'vendor', 'copilot', `${platform}-${arch}`, binaryName);
128→    return existsSync(packaged) ? packaged : undefined;
129→  }
130→
131→  return resolveUpwards(
132→    hostRuntime.appRootPath,
133→    join('node_modules', '@github', `copilot-${platform}-${arch}`, binaryName),
134→  );
135→}
136→
137→function resolveServerPath(hostRuntime: BackendHostRuntimeContext, serverName: string): string | undefined {
138→  if (hostRuntime.isPackaged) {
139→    return firstExistingPath([
140→      join(hostRuntime.appRootPath, 'resources', serverName, 'index.js'),
141→      join(hostRuntime.appRootPath, 'dist', 'resources', serverName, 'index.js'),
142→    ]);
143→  }
144→  return resolveUpwards(
145→    hostRuntime.appRootPath,
146→    join('packages', serverName, 'dist', 'index.js'),
147→  );
148→}
149→
150→function resolveRipgrepPath(hostRuntime: BackendHostRuntimeContext): string | undefined {
151→  const platform = process.platform === 'win32'
152→    ? 'x64-win32'
153→    : process.platform === 'darwin'
154→      ? (process.arch === 'arm64' ? 'arm64-darwin' : 'x64-darwin')
155→      : (process.arch === 'arm64' ? 'arm64-linux' : 'x64-linux');
156→  const binaryName = process.platform === 'win32' ? 'rg.exe' : 'rg';
157→  const ripgrepRelative = join(
158→    'node_modules',
159→    '@anthropic-ai',
160→    'claude-agent-sdk',
161→    'vendor',
162→    'ripgrep',
163→    platform,
164→    binaryName,
165→  );
166→
167→  if (hostRuntime.isPackaged) {
168→    const packaged = join(hostRuntime.appRootPath, ripgrepRelative);
169→    if (existsSync(packaged)) return packaged;
170→  }
171→
172→  const fromHostRoot = resolveUpwards(hostRuntime.appRootPath, ripgrepRelative, 10);
173→  if (fromHostRoot) return fromHostRoot;
174→
175→  const cwdFallback = join(process.cwd(), ripgrepRelative);
176→  if (existsSync(cwdFallback)) return cwdFallback;
177→
178→  // Non-packaged (headless server, dev mode): fall back to system rg via PATH.
179→  // Packaged apps must use vendored binary only — never resolve from PATH
180→  // to avoid picking up an incompatible system install.
181→  if (!hostRuntime.isPackaged) {
182→    try {
183→      const whichCmd = process.platform === 'win32' ? 'where' : 'which';
184→      const systemRg = execFileSync(whichCmd, ['rg'], { encoding: 'utf-8' }).trim();
185→      if (systemRg && existsSync(systemRg)) return systemRg;
186→    } catch { /* system rg not found */ }
187→  }
188→
189→  return undefined;
190→}
191→
192→export function resolveBackendRuntimePaths(hostRuntime: BackendHostRuntimeContext): ResolvedBackendRuntimePaths {
193→  const bundledRuntimePath = hostRuntime.nodeRuntimePath || resolveBundledRuntimePath(hostRuntime);
194→
195→  return {
196→    claudeCliPath: resolveClaudeCliPath(hostRuntime),
197→    claudeInterceptorPath: resolveClaudeInterceptorPath(hostRuntime),
198→    interceptorBundlePath: resolveInterceptorBundlePath(hostRuntime),
199→    copilotCliPath: resolveCopilotCliPath(hostRuntime),
200→    sessionServerPath: resolveServerPath(hostRuntime, 'session-mcp-server'),
201→    bridgeServerPath: resolveServerPath(hostRuntime, 'bridge-mcp-server'),
202→    piServerPath: resolveServerPath(hostRuntime, 'pi-agent-server'),
203→    nodeRuntimePath: hostRuntime.nodeRuntimePath || bundledRuntimePath || process.execPath,
204→    bundledRuntimePath,
205→  };
206→}
207→
208→export function resolveBackendHostTooling(hostRuntime: BackendHostRuntimeContext): ResolvedBackendHostTooling {
209→  return {
210→    ripgrepPath: resolveRipgrepPath(hostRuntime),
211→  };
212→}
