179→/**
180→ * Get default SDK options for spawning the Claude Code subprocess.
181→ *
182→ * @param envOverrides - Per-session environment variable overrides.
183→ *   These are spread AFTER process.env so they take precedence.
184→ *   Used to pass per-session config like ANTHROPIC_BASE_URL that would
185→ *   otherwise be clobbered by concurrent sessions mutating process.env.
186→ */
187→export function buildClaudeSubprocessEnv(
188→    envOverrides?: Record<string, string>,
189→): NodeJS.ProcessEnv {
190→    const env: NodeJS.ProcessEnv = {
191→        ...process.env,
192→        ...getProxyEnvVars(),
193→        ...envOverrides,
194→        // Propagate debug mode from argv flag OR existing env var
195→        CRAFT_DEBUG: (process.argv.includes('--debug') || process.env.CRAFT_DEBUG === '1') ? '1' : '0',
196→    };
197→
198→    // Bedrock must never be routed through the Claude SDK path.
199→    // Strip only Claude-specific Bedrock routing vars here; keep generic AWS_*
200→    // untouched so user shell/tooling behavior inside the subprocess remains intact.
201→    delete env.CLAUDE_CODE_USE_BEDROCK;
202→    delete env.AWS_BEARER_TOKEN_BEDROCK;
203→    delete env.ANTHROPIC_BEDROCK_BASE_URL;
204→
205→    return env;
206→}
