208→export function getDefaultOptions(envOverrides?: Record<string, string>): Partial<Options> {
209→    // Repair corrupted ~/.claude.json before the SDK subprocess reads it
210→    ensureClaudeConfig();
211→
212→    // SECURITY: Disable Bun's automatic .env file loading in the SDK subprocess.
213→    // Without this, Bun loads .env from the subprocess cwd (user's working directory),
214→    // which can inject ANTHROPIC_API_KEY and override our OAuth auth — silently charging
215→    // the user's API key instead of their Max subscription.
216→    // See: https://github.com/lukilabs/craft-agents-oss/issues/39
217→    // Use platform-appropriate null device (NUL on Windows, /dev/null on Unix)
218→    const nullDevice = process.platform === 'win32' ? 'NUL' : '/dev/null';
219→    const envFileFlag = `--env-file=${nullDevice}`;
220→
221→    // If custom path is set (e.g., for Electron), use it with minimal options
222→    if (customPathToClaudeCodeExecutable) {
223→        const executableArgs = [envFileFlag];
224→        // Add interceptor preload if path is set (needed for cache TTL patching)
225→        if (customInterceptorPath) {
226→            executableArgs.push('--preload', customInterceptorPath);
227→        }
228→        return {
229→            pathToClaudeCodeExecutable: customPathToClaudeCodeExecutable,
230→            // Use custom executable if set, otherwise default to 'bun'
231→            executable: (customExecutable || 'bun') as 'bun',
232→            executableArgs,
233→            env: buildClaudeSubprocessEnv(envOverrides)
234→        };
235→    }
236→
237→    if (typeof CRAFT_AGENT_CLI_VERSION !== 'undefined' && CRAFT_AGENT_CLI_VERSION != null) {
238→        const baseDir = join(homedir(), '.local', 'share', 'craft', 'versions', CRAFT_AGENT_CLI_VERSION);
239→        return {
240→            pathToClaudeCodeExecutable: join(baseDir, 'claude-agent-sdk', 'cli.js'),
241→            // Use the compiled binary itself as the runtime via BUN_BE_BUN=1
242→            // This makes the compiled Bun executable act as the full Bun CLI,
243→            // eliminating the need for external Node or Bun installation
244→            executable: process.execPath as 'bun',
245→            // Inject network interceptor into SDK subprocess for API error capture and MCP schema injection
246→            executableArgs: [envFileFlag, '--preload', join(baseDir, 'unified-network-interceptor.ts')],
247→            env: {
248→                ...buildClaudeSubprocessEnv(envOverrides),
249→                BUN_BE_BUN: '1',
250→            }
251→        }
252→    }
253→    return {
254→        executableArgs: [envFileFlag],
255→        env: buildClaudeSubprocessEnv(envOverrides)
256→    };
257→}
