  1→/**
  2→ * Event Queue for Async Generator Pattern
  3→ *
  4→ * Bridges async event handlers (.on() listeners) with AsyncGenerator<AgentEvent>.
  5→ * Used by CodexAgent and CopilotAgent where events arrive asynchronously from
  6→ * separate notification handlers, unlike ClaudeAgent's synchronous for-await loop.
  7→ *
  8→ * Pattern:
  9→ *   handler calls enqueue(event) → pushes to queue, wakes waiters
 10→ *   chat() loop calls drain()   → yields queued events, waits when empty
 11→ *   handler calls complete()    → signals no more events
 12→ */
 13→
 14→import type { AgentEvent } from '@craft-agent/core/types';
 15→
 16→export class EventQueue {
 17→  private queue: AgentEvent[] = [];
 18→  private resolvers: Array<(done: boolean) => void> = [];
 19→  private done: boolean = false;
 20→
 21→  /**
 22→   * Enqueue an event and wake any waiting consumers.
 23→   */
 24→  enqueue(event: AgentEvent): void {
 25→    this.queue.push(event);
 26→    this.signal(false);
 27→  }
 28→
 29→  /**
 30→   * Signal that the turn is complete — no more events expected.
 31→   * Wakes all waiting consumers with done=true.
 32→   */
 33→  complete(): void {
 34→    this.done = true;
 35→    this.signal(true);
 36→  }
 37→
 38→  /**
 39→   * Reset queue state for a new turn.
 40→   * Must be called before each chat() invocation.
 41→   */
 42→  reset(): void {
 43→    this.queue = [];
 44→    this.resolvers = [];
 45→    this.done = false;
 46→  }
 47→
 48→  /**
 49→   * Async generator that yields events as they arrive.
 50→   * Completes when complete() is called and the queue is drained.
 51→   */
 52→  async *drain(): AsyncGenerator<AgentEvent> {
 53→    while (true) {
 54→      const isDone = await this.waitForEvent();
 55→
 56→      // Yield all queued events
 57→      while (this.queue.length > 0) {
 58→        yield this.queue.shift()!;
 59→      }
 60→
 61→      if (isDone) break;
 62→    }
 63→  }
 64→
 65→  /**
 66→   * Check if the queue has pending events.
 67→   */
 68→  get hasPending(): boolean {
 69→    return this.queue.length > 0;
 70→  }
 71→
 72→  /**
 73→   * Check if the queue has been marked complete.
 74→   */
 75→  get isComplete(): boolean {
 76→    return this.done;
 77→  }
 78→
 79→  // ============================================================
 80→  // Internal
 81→  // ============================================================
 82→
 83→  /**
 84→   * Wake all waiting consumers.
 85→   */
 86→  private signal(done: boolean): void {
 87→    const pending = this.resolvers.splice(0);
 88→    for (const resolve of pending) {
 89→      resolve(done);
 90→    }
 91→  }
 92→
 93→  /**
 94→   * Wait for events to be available or completion signal.
 95→   * Returns true when turn is complete and queue is empty.
 96→   */
 97→  private waitForEvent(): Promise<boolean> {
 98→    if (this.queue.length > 0 || this.done) {
 99→      return Promise.resolve(this.done && this.queue.length === 0);
100→    }
101→    return new Promise((resolve) => {
102→      this.resolvers.push(resolve);
103→    });
104→  }
105→}
