  1→/**
  2→ * Session Types
  3→ *
  4→ * Types for workspace-scoped sessions.
  5→ * Sessions are stored at {workspaceRootPath}/sessions/{id}/session.jsonl
  6→ *
  7→ * JSONL Format:
  8→ * - Line 1: SessionHeader (metadata + pre-computed fields for fast list loading)
  9→ * - Lines 2+: StoredMessage (one message per line)
 10→ */
 11→
 12→import type { PermissionMode } from '../agent/mode-manager.ts';
 13→import type { ThinkingLevel } from '../agent/thinking-levels.ts';
 14→import type { StoredAttachment, MessageRole, ToolStatus, AuthRequestType, AuthStatus, CredentialInputMode, StoredMessage } from '@craft-agent/core/types';
 15→
 16→/**
 17→ * Session fields that persist to disk.
 18→ * Add new fields here - they automatically propagate to JSONL read/write
 19→ * via pickSessionFields() utility.
 20→ *
 21→ * IMPORTANT: When adding a new field:
 22→ * 1. Add it to this array
 23→ * 2. Add it to SessionConfig interface below
 24→ * 3. Done - serialization is automatic
 25→ */
 26→export const SESSION_PERSISTENT_FIELDS = [
 27→  // Identity
 28→  'id', 'workspaceRootPath', 'sdkSessionId', 'sdkCwd',
 29→  // Timestamps
 30→  'createdAt', 'lastUsedAt', 'lastMessageAt',
 31→  // Display
 32→  'name', 'isFlagged', 'sessionStatus', 'labels', 'hidden',
 33→  // Read tracking
 34→  'lastReadMessageId', 'hasUnread',
 35→  // Config
 36→  'enabledSourceSlugs', 'permissionMode', 'previousPermissionMode', 'workingDirectory',
 37→  // Model/Connection
 38→  'model', 'llmConnection', 'connectionLocked', 'thinkingLevel',
 39→  // Sharing
 40→  'sharedUrl', 'sharedId',
 41→  // Plan execution
 42→  'pendingPlanExecution',
 43→  // Archive
 44→  'isArchived', 'archivedAt',
 45→  // Branching
 46→  'branchFromMessageId',
 47→  'branchFromSdkSessionId',
 48→  'branchFromSessionPath',
 49→  'branchFromSdkCwd',
 50→  'branchFromSdkTurnId',
 51→  // Remote transfer handoff
 52→  'transferredSessionSummary',
 53→  'transferredSessionSummaryApplied',
 54→  // Automation origin
 55→  'triggeredBy',
 56→] as const;
 57→
 58→export type SessionPersistentField = typeof SESSION_PERSISTENT_FIELDS[number];
 59→
 60→/**
 61→ * Session status (user-controlled, never automatic)
 62→ *
 63→ * Dynamic status ID referencing workspace status config.
 64→ * Validated at runtime via validateSessionStatus().
 65→ * Falls back to 'todo' if status doesn't exist.
 66→ */
 67→export type SessionStatus = string;
