 97→ * Session configuration (persisted metadata)
 98→ */
 99→export interface SessionConfig {
100→  id: string;
101→  /** SDK session ID (captured after first message) */
102→  sdkSessionId?: string;
103→  /** Workspace root path this session belongs to */
