105→  /** Optional user-defined name */
106→  name?: string;
107→  createdAt: number;
108→  lastUsedAt: number;
109→  /** Timestamp of last meaningful message (user or final assistant). Used for date grouping in session list.
110→   *  Separate from lastUsedAt which tracks any session access (auto-save, open to read, etc.). */
111→  lastMessageAt?: number;
112→  /** Whether this session is flagged */
113→  isFlagged?: boolean;
114→  /** Permission mode for this session ('safe', 'ask', 'allow-all') */
115→  permissionMode?: PermissionMode;
