119→  sessionStatus?: SessionStatus;
120→  /** Labels applied to this session (bare IDs or "id::value" entries) */
121→  labels?: string[];
122→  /** ID of last message user has read */
123→  lastReadMessageId?: string;
124→  /**
125→   * Explicit unread flag - single source of truth for NEW badge.
126→   * Set to true when assistant message completes while user is NOT viewing.
127→   * Set to false when user views the session (and not processing).
128→   */
129→  hasUnread?: boolean;
130→  /** Per-session source selection (source slugs) */
