134→  /** SDK cwd for session storage - set once at creation, never changes. Ensures SDK can find session transcripts regardless of workingDirectory changes. */
135→  sdkCwd?: string;
136→  /** Shared viewer URL (if shared via viewer) */
137→  sharedUrl?: string;
138→  /** Shared session ID in viewer (for revoke) */
139→  sharedId?: string;
