169→  /**
170→   * Message ID this session was branched from.
171→   * Branching semantics are a hard cutoff: model context must not include parent messages after this message.
172→   */
173→  branchFromMessageId?: string;
174→  /**
175→   * Parent session's SDK session ID (optional, only for provider strategies that support strict SDK-level forking).
176→   */
