 12→  },
 13→  prepareRuntime: ({ hostRuntime, resolvedPaths }) => {
 14→    applyAnthropicRuntimeBootstrap(hostRuntime, resolvedPaths);
 15→  },
 16→  buildRuntime: () => ({}),
 17→  fetchModels: async ({ connection, credentials }) => {
 18→    // After legacy migration, only direct 'anthropic' connections reach this driver.
 19→    // iam_credentials and service_account_file are no longer valid auth types for anthropic.
 20→
 21→    const apiKey = credentials.apiKey;
 22→    const oauthAccessToken = credentials.oauthAccessToken;
 23→
 24→    if (!apiKey && !oauthAccessToken) {
 25→      throw new Error('Anthropic credentials required to fetch models');
 26→    }
 27→
 28→    const baseUrl = connection.baseUrl || 'https://api.anthropic.com';
 29→    const headers: Record<string, string> = {
 30→      'anthropic-version': '2023-06-01',
 31→    };
 32→    if (apiKey) {
 33→      headers['x-api-key'] = apiKey;
 34→    } else {
 35→      headers.authorization = `Bearer ${oauthAccessToken}`;
 36→    }
 37→
 38→    const allRawModels: Array<{
 39→      id: string;
 40→      display_name: string;
 41→      created_at: string;
 42→      type: string;
 43→    }> = [];
 44→    let afterId: string | undefined;
 45→
 46→    do {
 47→      const params = new URLSearchParams({ limit: '100' });
 48→      if (afterId) params.set('after_id', afterId);
 49→
 50→      const response = await fetch(`${baseUrl}/v1/models?${params}`, { headers });
 51→      if (!response.ok) {
 52→        throw new Error(`Anthropic /v1/models failed: ${response.status} ${response.statusText}`);
 53→      }
 54→
 55→      const data = await response.json() as {
 56→        data: Array<{ id: string; display_name: string; created_at: string; type: string }>;
 57→        has_more: boolean;
 58→        first_id: string;
 59→        last_id: string;
 60→      };
 61→      if (data.data) allRawModels.push(...data.data);
 62→
 63→      if (data.has_more && data.last_id) {
 64→        afterId = data.last_id;
 65→      } else {
 66→        break;
 67→      }
 68→    } while (true);
 69→
 70→    if (allRawModels.length === 0) {
 71→      throw new Error('No models returned from Anthropic API');
 72→    }
 73→
 74→    const models = allRawModels
 75→      .filter(m => m.id.startsWith('claude-') && !m.id.startsWith('claude-2') && !m.id.startsWith('claude-instant') && !m.id.startsWith('claude-1'))
 76→      .map(m => ({
 77→        id: m.id,
 78→        name: m.display_name,
 79→        shortName: (() => {
 80→          const stripped = m.id
 81→            .replace('claude-', '')
 82→            .replace(/-\d{8}$/, '')
 83→            .replace(/-latest$/, '');
 84→          const variant = stripped
 85→            .replace(/^[\d.-]+/, '')
 86→            .replace(/-[\d.]+$/, '')
 87→            .replace(/^-/, '');
 88→          return variant ? variant.charAt(0).toUpperCase() + variant.slice(1) : stripped;
 89→        })(),
 90→        description: '',
 91→        provider: 'anthropic' as const,
 92→        contextWindow: getModelContextWindow(m.id) ?? 200_000,
 93→      }));
 94→
 95→    return { models };
 96→  },
 97→  validateStoredConnection: async ({ slug, connection, credentialManager }) => {
 98→    // After legacy migration, only direct 'anthropic' connections reach this driver.
 99→
100→    if (connection.providerType === 'anthropic' && connection.authType === 'oauth') {
101→      const { getValidClaudeOAuthToken } = await import('../../../../auth/state.ts');
102→      const tokenResult = await getValidClaudeOAuthToken(slug);
103→      if (!tokenResult.accessToken) {
104→        const errorMsg = tokenResult.migrationRequired?.message || 'OAuth token expired. Please re-authenticate.';
105→        return { success: false, error: errorMsg };
106→      }
107→      return { success: true };
108→    }
109→
110→    let apiKey: string | null = null;
111→    let oauthToken: string | null = null;
112→
113→    if (connection.authType === 'api_key' || connection.authType === 'api_key_with_endpoint') {
114→      apiKey = await credentialManager.getLlmApiKey(slug);
115→    } else if (connection.authType === 'bearer_token') {
116→      oauthToken = await credentialManager.getLlmApiKey(slug);
117→    } else if (connection.authType === 'environment') {
118→      apiKey = process.env.ANTHROPIC_API_KEY || null;
119→      if (!apiKey) {
120→        return { success: false, error: 'ANTHROPIC_API_KEY environment variable not set' };
121→      }
122→    } else if (connection.authType === 'none') {
123→      apiKey = 'ollama';
124→    }
125→
126→    if (!apiKey && !oauthToken && connection.authType !== 'none') {
127→      return { success: false, error: 'Could not retrieve credentials' };
128→    }
129→
130→    const testModel = connection.defaultModel!;
131→    const validationResult = await validateAnthropicConnection({
132→      model: testModel,
133→      apiKey: apiKey || undefined,
134→      oauthToken: oauthToken || undefined,
135→      baseUrl: connection.baseUrl || undefined,
136→    });
137→
138→    if (!validationResult.success) {
139→      return { success: false, error: validationResult.error };
140→    }
141→
142→    return { success: true };
143→  },
144→};
