154→/**
155→ * Create backend from a pre-resolved context and provider-agnostic core config.
156→ * Provider-specific runtime resolution happens via internal driver registry.
157→ */
158→export function createBackendFromResolvedContext(args: {
159→  context: ResolvedBackendContext;
160→  coreConfig: CoreBackendConfig;
161→  hostRuntime: BackendHostRuntimeContext;
162→  providerOptions?: BackendProviderOptions;
163→}): AgentBackend {
164→  const { context, coreConfig, hostRuntime, providerOptions } = args;
165→  const { driver, resolvedPaths } = resolveDriverRuntime(context.provider, hostRuntime);
166→
167→  const buildArgs = {
168→    context,
169→    coreConfig,
170→    hostRuntime,
171→    resolvedPaths,
172→    providerOptions,
173→  };
174→
175→  driver.prepareRuntime?.(buildArgs);
176→  const runtime = driver.buildRuntime(buildArgs);
177→
178→  const config: ResolvedBackendConfig = {
179→    ...coreConfig,
180→    provider: context.provider,
181→    providerType: context.connection?.providerType ?? getDefaultProviderType(context.provider),
182→    authType: context.authType || getDefaultAuthType(context.provider),
183→    model: context.resolvedModel,
184→    connectionSlug: context.connection?.slug,
185→    runtime,
186→  };
187→
188→  return createBackend(config);
189→}
