 12→const encoder = new TextEncoder();
 13→const decoder = new TextDecoder();
 14→
 15→async function runThroughProcessor(
 16→  processor: TransformStream<Uint8Array, Uint8Array>,
 17→  chunks: string[],
 18→): Promise<string> {
 19→  const input = new ReadableStream<Uint8Array>({
 20→    start(controller) {
 21→      for (const chunk of chunks) controller.enqueue(encoder.encode(chunk));
 22→      controller.close();
 23→    },
 24→  });
 25→
 26→  const output = input.pipeThrough(processor);
 27→  const reader = output.getReader();
 28→  let result = '';
 29→  while (true) {
 30→    const { value, done } = await reader.read();
 31→    if (done) break;
 32→    if (value) result += decoder.decode(value, { stream: true });
 33→  }
 34→  result += decoder.decode();
 35→  return result;
 36→}
