 39→// ============================================================================
 40→// PROXY CONFIGURATION (from env vars injected by parent process)
 41→// ============================================================================
 42→
 43→const PROXY_URL = process.env.HTTPS_PROXY || process.env.https_proxy
 44→  || process.env.HTTP_PROXY || process.env.http_proxy || '';
 45→const NO_PROXY = process.env.NO_PROXY || process.env.no_proxy || '';
 46→
 47→/** Strip credentials from a proxy URL, returning only scheme://host:port */
 48→function redactProxyUrl(proxyUrl: string): string {
 49→  try {
 50→    const parsed = new URL(proxyUrl);
 51→    parsed.username = '';
 52→    parsed.password = '';
 53→    return parsed.toString().replace(/\/$/, '');
 54→  } catch {
 55→    return '(invalid proxy URL)';
 56→  }
 57→}
 58→
 59→/** Parse NO_PROXY into hostname patterns for bypass matching. */
 60→const noProxyPatterns: string[] = NO_PROXY
 61→  ? NO_PROXY.split(',').map(s => s.trim().toLowerCase()).filter(Boolean)
 62→  : [];
 63→
 64→/** Check if a URL should bypass the proxy based on NO_PROXY rules. */
 65→function shouldBypassProxy(url: string): boolean {
 66→  if (noProxyPatterns.length === 0) return false;
 67→  try {
 68→    const hostname = new URL(url).hostname.toLowerCase();
 69→    return noProxyPatterns.some(pattern => {
 70→      if (pattern === '*') return true;
 71→      // .example.com matches any subdomain of example.com
 72→      if (pattern.startsWith('.')) return hostname.endsWith(pattern);
 73→      // exact match or subdomain match
 74→      return hostname === pattern || hostname.endsWith('.' + pattern);
 75→    });
 76→  } catch {
 77→    return false;
 78→  }
 79→}
 80→
 81→/** Get the proxy URL for a given request URL, or undefined to go direct. */
 82→function getProxyForUrl(url: string): string | undefined {
 83→  if (!PROXY_URL || shouldBypassProxy(url)) return undefined;
 84→  return PROXY_URL;
 85→}
 86→
 87→if (PROXY_URL) {
 88→  debugLog(`[proxy] Configured: ${redactProxyUrl(PROXY_URL)}${NO_PROXY ? `, NO_PROXY: ${NO_PROXY}` : ''}`);
 89→}
