 52→/**
 53→ * Get the Bun download filename for a platform/arch combination
 54→ */
 55→export function getBunDownloadName(platform: Platform, arch: Arch): string {
 56→  const archMap: Record<Arch, string> = {
 57→    x64: 'x64',
 58→    arm64: 'aarch64',
 59→  };
 60→
 61→  const platformMap: Record<Platform, string> = {
 62→    darwin: 'darwin',
 63→    win32: 'windows',
 64→    linux: 'linux',
 65→  };
 66→
 67→  const bunArch = archMap[arch];
 68→  const bunPlatform = platformMap[platform];
 69→
 70→  // Windows and Linux x64 use baseline build for broader CPU compatibility (no AVX2 requirement)
 71→  if ((platform === 'win32' || platform === 'linux') && arch === 'x64') {
 72→    return `bun-${bunPlatform}-x64-baseline`;
 73→  }
 74→
 75→  return `bun-${bunPlatform}-${bunArch}`;
 76→}
