 19→/**
 20→ * Ensure ~/.claude.json exists and contains valid, BOM-free JSON before
 21→ * the SDK subprocess starts.
 22→ *
 23→ * Background: The SDK's cli.js reads this file on startup. If it's missing
 24→ * (with a .backup file present), empty, BOM-prefixed, or contains invalid JSON,
 25→ * the CLI writes plain-text error/recovery messages to process.stdout.
 26→ * The SDK transport expects only JSON on stdout, so any plain text causes:
 27→ *   "CLI output was not valid JSON"
 28→ *
 29→ * Known causes of corruption (from claude-code GitHub issues):
 30→ *   - UTF-8 BOM encoding on Windows (#14442) — editors/auth writes add BOM prefix
 31→ *   - Empty file from crash during write (#2593) — CLI truncates before writing
 32→ *   - Race condition with concurrent sessions (#18998) — no file locking
 33→ *   - Missing file with stale .backup — CLI writes recovery instructions to stdout
 34→ *
 35→ * This runs once per process lifetime (not on every message), unless
 36→ * resetClaudeConfigCheck() is called to force a re-check after error recovery.
 37→ */
 38→function ensureClaudeConfig(): void {
 39→    if (claudeConfigChecked) return;
 40→    claudeConfigChecked = true;
 41→
 42→    const configPath = join(homedir(), '.claude.json');
 43→
 44→    // Clean up stale .backup file — if present and .claude.json is missing,
 45→    // the CLI writes "A backup file exists at..." to stdout, crashing the SDK.
 46→    // We remove it so the CLI sees a clean "missing file" state (which it handles silently).
 47→    const backupPath = `${configPath}.backup`;
 48→    if (existsSync(backupPath)) {
 49→        try {
 50→            unlinkSync(backupPath);
 51→            debug('[options] Removed stale ~/.claude.json.backup');
 52→        } catch (err) {
 53→            debug(`[options] Failed to remove ~/.claude.json.backup: ${err}`);
 54→        }
 55→    }
 56→
 57→    // Clean up .corrupted.* files — these accumulate on Windows and signal
 58→    // to the CLI that a previous corruption was detected, altering its stdout output.
 59→    try {
 60→        const homeDir = homedir();
 61→        const files = readdirSync(homeDir);
 62→        for (const file of files) {
 63→            if (file.startsWith('.claude.json.corrupted.')) {
 64→                try {
 65→                    unlinkSync(join(homeDir, file));
 66→                    debug(`[options] Removed stale ${file}`);
 67→                } catch { /* best effort */ }
 68→            }
 69→        }
 70→    } catch {
 71→        // If we can't read homedir, we'll still try the main repair below
 72→    }
 73→
 74→    // If file doesn't exist, create it with minimal valid JSON.
 75→    // The CLI handles truly missing files (no backup) silently, but creating
 76→    // the file is safer — it prevents any future backup-related stdout pollution.
 77→    if (!existsSync(configPath)) {
 78→        debug('[options] ~/.claude.json missing, creating with {}');
 79→        writeConfigSafe(configPath, '{}');
 80→        return;
 81→    }
 82→
 83→    // File exists — read and validate
 84→    try {
 85→        const raw = readFileSync(configPath, 'utf-8');
 86→
 87→        // Strip UTF-8 BOM if present (common on Windows — see claude-code#14442).
 88→        // The BOM is valid UTF-8 but invalid as a JSON start character, so the CLI
 89→        // rejects the file and writes an error to stdout.
 90→        const content = raw.startsWith(UTF8_BOM) ? raw.slice(1) : raw;
 91→        const hasBom = raw !== content;
 92→
 93→        if (content.trim().length === 0) {
 94→            // Empty file (or BOM-only) — write minimal valid JSON
 95→            debug(`[options] ~/.claude.json is empty${hasBom ? ' (had BOM)' : ''}, resetting to {}`);
 96→            writeConfigSafe(configPath, '{}');
 97→            return;
 98→        }
 99→
100→        // Try to parse the (BOM-stripped) content
101→        JSON.parse(content);
102→
103→        if (hasBom) {
104→            // Valid JSON but had BOM prefix — rewrite without BOM to prevent
105→            // the CLI from rejecting it. Preserves all existing config data.
106→            debug('[options] ~/.claude.json had UTF-8 BOM, rewriting without BOM');
107→            writeConfigSafe(configPath, content);
108→        }
109→        // else: valid JSON, no BOM — nothing to do
110→    } catch {
111→        // File exists but contains invalid JSON — reset to minimal valid state.
112→        // This loses user's CLI config but prevents the subprocess crash.
113→        debug('[options] ~/.claude.json is corrupted, resetting to {}');
114→        writeConfigSafe(configPath, '{}');
115→    }
116→}
